"use client";

import { useSearchParams, useRouter } from "next/navigation";
import Header from "../components/Header";
import Footer from "../components/Footer";
import { XCircle, RefreshCw, ArrowLeft, AlertTriangle } from "lucide-react";
import { Button } from "@/app/components/ui/button";
import { Card, CardContent } from "@/app/components/ui/card";

export default function PaymentFailedPage() {
    const searchParams = useSearchParams();
    const router = useRouter();

    const reason = searchParams.get("reason");
    const itemId = searchParams.get("item");

    const getErrorMessage = () => {
        switch (reason) {
            case "incomplete":
                return "The payment was not completed. Please try again.";
            case "booking_not_found":
                return "We couldn't find the booking record. Please contact support.";
            case "verification_error":
                return "There was an error verifying your payment with the gateway.";
            case "missing_data":
                return "Payment data is missing. Please restart the process.";
            default:
                return "An unexpected error occurred during the payment process.";
        }
    };

    return (
        <div className="min-h-screen flex flex-col bg-background">
            <Header />

            <main className="flex-1 flex flex-col items-center justify-center p-4 md:p-8">
                <div className="max-w-md w-full space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
                    {/* Error Icon */}
                    <div className="flex flex-col items-center space-y-4 text-center">
                        <div className="relative">
                            <div className="absolute inset-0 bg-destructive/20 rounded-full blur-2xl" />
                            <div className="relative h-24 w-24 bg-destructive rounded-full flex items-center justify-center shadow-2xl">
                                <XCircle className="h-12 w-12 text-destructive-foreground" />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <h1 className="text-3xl font-black tracking-tight text-foreground">Payment Failed</h1>
                            <p className="text-muted-foreground font-medium">Something went wrong with your transaction.</p>
                        </div>
                    </div>

                    {/* Error Card */}
                    <Card className="border-destructive/20 shadow-xl bg-card/50 backdrop-blur-sm overflow-hidden">
                        <CardContent className="p-6">
                            <div className="flex items-start gap-4">
                                <div className="h-10 w-10 bg-destructive/10 rounded-full flex items-center justify-center shrink-0">
                                    <AlertTriangle className="h-5 w-5 text-destructive" />
                                </div>
                                <div className="space-y-1">
                                    <h3 className="font-bold text-sm text-foreground uppercase tracking-wider">Error Details</h3>
                                    <p className="text-sm text-muted-foreground leading-relaxed">
                                        {getErrorMessage()}
                                    </p>
                                </div>
                            </div>
                        </CardContent>
                    </Card>

                    {/* Action Buttons */}
                    <div className="flex flex-col gap-3">
                        <Button 
                            onClick={() => itemId ? router.push(`/products/${itemId}`) : router.push("/")}
                            className="h-12 w-full gap-2 text-sm font-bold uppercase tracking-widest bg-primary hover:bg-primary/90 shadow-lg"
                        >
                            <RefreshCw className="h-4 w-4" />
                            Try Again
                        </Button>
                        
                        <Button 
                            variant="ghost" 
                            onClick={() => router.back()}
                            className="h-11 gap-2 text-xs font-bold uppercase tracking-wider text-muted-foreground hover:text-foreground"
                        >
                            <ArrowLeft className="h-4 w-4" />
                            Go Back
                        </Button>
                    </div>

                    <div className="text-center">
                        <p className="text-[10px] text-muted-foreground/40 font-bold uppercase tracking-[0.3em]">
                            Secure Marketplace Verification
                        </p>
                    </div>
                </div>
            </main>

            <Footer />
        </div>
    );
}
