"use client";

import { useState } from "react";
import { Star, X, Loader2 } from "lucide-react";
import { Button } from "./ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "./ui/card";
import { Input } from "./ui/input";
import { toast } from "sonner";
import { addReview, markSingleNotificationAsRead } from "../lib/api";

interface RatingModalProps {
    isOpen: boolean;
    onClose: () => void;
    sellerName: string;
    sellerId: string;
    itemId: string;
    itemName: string;
    invoiceId: string;
    notificationId: string;
}

export default function RatingModal({ isOpen, onClose, sellerName, sellerId, itemId, itemName, invoiceId, notificationId }: RatingModalProps) {
    const [rating, setRating] = useState(0);
    const [hoverRating, setHoverRating] = useState(0);
    const [comment, setComment] = useState("");
    const [loading, setLoading] = useState(false);

    if (!isOpen) return null;

    const handleSubmit = async () => {
        if (rating === 0) {
            toast.error("Please select a star rating");
            return;
        }

        setLoading(true);
        try {
            const res = await addReview({
                itemId,
                sellerId,
                rating,
                comment,
                invoiceId
            });

            if (res.success) {
                toast.success(`Thank you for rating ${sellerName}!`);
                
                // Mark the deal_closed notification as read so it doesn't prompt again
                if (notificationId) {
                    try {
                        await markSingleNotificationAsRead(notificationId);
                        // Optional: trigger header update
                        window.dispatchEvent(new CustomEvent('notificationsUpdated'));
                    } catch (e) {
                        console.error("Failed to mark notification as read", e);
                    }
                }
                
                onClose();
            }
        } catch (error: any) {
            toast.error(error.message || "Failed to submit review");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
            <Card className="w-full max-w-md shadow-2xl border-none animate-in fade-in zoom-in duration-300">
                <CardHeader className="relative pb-2">
                    <Button 
                        variant="ghost" 
                        size="icon" 
                        className="absolute right-4 top-4 rounded-full"
                        onClick={onClose}
                    >
                        <X className="h-4 w-4" />
                    </Button>
                    <CardTitle className="text-xl font-bold flex items-center gap-2">
                        Rate Your Experience
                    </CardTitle>
                    <CardDescription>
                        How was your transaction for <span className="font-semibold text-foreground">"{itemName}"</span> with <span className="font-semibold text-primary">{sellerName}</span>?
                    </CardDescription>
                </CardHeader>
                <CardContent className="space-y-6 pt-4">
                    {/* Stars */}
                    <div className="flex flex-col items-center gap-3">
                        <div className="flex gap-2">
                            {[1, 2, 3, 4, 5].map((star) => (
                                <button
                                    key={star}
                                    onMouseEnter={() => setHoverRating(star)}
                                    onMouseLeave={() => setHoverRating(0)}
                                    onClick={() => setRating(star)}
                                    className="transition-transform active:scale-90 hover:scale-110"
                                >
                                    <Star 
                                        className={`h-10 w-10 ${
                                            (hoverRating || rating) >= star 
                                                ? "fill-yellow-400 text-yellow-400" 
                                                : "text-muted-foreground/30"
                                        } transition-colors`}
                                    />
                                </button>
                            ))}
                        </div>
                        <span className="text-xs font-bold uppercase tracking-widest text-primary/60">
                            {rating === 5 ? "Excellent! 🌟" : 
                             rating === 4 ? "Very Good! ✨" :
                             rating === 3 ? "Good! 👍" :
                             rating === 2 ? "Could be better 😕" :
                             rating === 1 ? "Disappointing 😞" : "Click to rate"}
                        </span>
                    </div>

                    {/* Comment */}
                    <div className="space-y-2">
                        <label className="text-xs font-bold uppercase tracking-widest text-muted-foreground">Share your feedback (Optional)</label>
                        <Input 
                            placeholder="Write a brief comment about the seller..."
                            value={comment}
                            onChange={(e) => setComment(e.target.value)}
                            className="bg-muted/50 border-none focus-visible:ring-1 focus-visible:ring-primary"
                        />
                    </div>

                    <div className="flex flex-col gap-2 pt-2">
                        <Button 
                            className="w-full h-11 font-bold uppercase tracking-widest"
                            onClick={handleSubmit}
                            disabled={loading || rating === 0}
                        >
                            {loading ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
                            Submit Review
                        </Button>
                        <Button 
                            variant="ghost" 
                            className="w-full text-[10px] uppercase tracking-[0.2em] font-black text-muted-foreground"
                            onClick={onClose}
                        >
                            Skip for now
                        </Button>
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}
